# Creates a desktop shortcut that opens the SDS System in a clean "app mode"
# window (its own window, no address bar/tabs/bookmarks bar) instead of a
# regular browser tab, using the installed browser's --app flag. The DepEd
# SDO Camarines Norte seal is embedded below and used as the shortcut icon,
# so this is a single self-contained file — nothing else needs to be copied
# to the user's PC.
#
# Usage (run once per user PC, after the app's real URL is known):
#   powershell -ExecutionPolicy Bypass -File create-desktop-shortcut.ps1 -Url "http://<server-ip>:3000"

param(
    [Parameter(Mandatory = $true)]
    [string]$Url,

    [string]$Name = "SDS System"
)

$ErrorActionPreference = "Stop"

# Locate Edge (ships with Windows 10/11) or fall back to Chrome if installed instead.
$browser = "$env:ProgramFiles (x86)\Microsoft\Edge\Application\msedge.exe"
if (-not (Test-Path $browser)) { $browser = "$env:ProgramFiles\Microsoft\Edge\Application\msedge.exe" }
if (-not (Test-Path $browser)) { $browser = "$env:ProgramFiles (x86)\Google\Chrome\Application\chrome.exe" }
if (-not (Test-Path $browser)) { $browser = "$env:ProgramFiles\Google\Chrome\Application\chrome.exe" }
if (-not (Test-Path $browser)) {
    Write-Host "Could not find Edge or Chrome on this PC. Install one, or edit `$browser at the top of this script to point at your browser's .exe." -ForegroundColor Red
    exit 1
}

# Write the embedded icon out to disk once, so the .lnk has something to point at.
$iconDir = Join-Path $env:LOCALAPPDATA "SDSSystem"
New-Item -ItemType Directory -Force -Path $iconDir | Out-Null
$iconPath = Join-Path $iconDir "sds-icon.ico"
$iconBase64 = ""
[System.IO.File]::WriteAllBytes($iconPath, [System.Convert]::FromBase64String($iconBase64))

$desktop = [Environment]::GetFolderPath("Desktop")
$shortcutPath = Join-Path $desktop "$Name.lnk"

$shell = New-Object -ComObject WScript.Shell
$shortcut = $shell.CreateShortcut($shortcutPath)
$shortcut.TargetPath = $browser
$shortcut.Arguments = "--app=$Url"
$shortcut.Description = $Name
$shortcut.IconLocation = $iconPath
$shortcut.WorkingDirectory = $iconDir
$shortcut.Save()

Write-Host "Created desktop shortcut: $shortcutPath" -ForegroundColor Green
Write-Host "Opens: $Url" -ForegroundColor Green
